/// `enum llm_tensor_layer` (llama-arch.h).
#[allow(non_camel_case_types)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum LlmTensorLayer {
    INPUT,
    REPEATING,
    OUTPUT,
}

/// `LLM_KV::operator()(kv)` — resolve a KV key name for the given arch.
///
/// Mirrors `::format(LLM_KV_NAMES.at(kv), LLM_ARCH_NAMES.at(arch))`: templates
/// with a `%s` slot get the arch name (e.g. `qwen2.block_count`), fixed keys
/// (tokenizer/general/split/adapter/xielu) come back verbatim.
pub fn kv_name(arch: LlmArch, kv: LlmKv) -> String {
    let tmpl = kv.template();
    if tmpl.contains('%') {
        debug_assert!(
            tmpl.matches("%s").count() <= 1,
            "unexpected multi-%s template: {tmpl}"
        );
        tmpl.replacen("%s", arch.name(), 1)
    } else {
        tmpl.to_string()
    }
}

/// `LLM_TN(arch)(tensor, bid)` — tensor name with the block id substituted
/// (`bid < 0` leaves non-`%d` templates untouched, like the C formatter).
pub fn tensor_name(tensor: LlmTensor, blk: i32) -> String {
    format_tensor(tensor, blk, -1)
}

/// `LLM_TN(arch)(tensor, bid, xid)` — also substitutes the second `%d`
/// (per-expert tensors, e.g. `blk.0.ffn_gate.3`).
pub fn tensor_name_xid(tensor: LlmTensor, blk: i32, xid: i32) -> String {
    format_tensor(tensor, blk, xid)
}

/// `LLM_TN(arch)(tensor, suffix, bid, xid)` — appends `.suffix`
/// (e.g. `blk.3.attn_norm.weight`).
pub fn tensor_name_suffix(tensor: LlmTensor, suffix: &str, blk: i32, xid: i32) -> String {
    let mut name = format_tensor(tensor, blk, xid);
    name.push('.');
    name.push_str(suffix);
    name
}

fn format_tensor(tensor: LlmTensor, blk: i32, xid: i32) -> String {
    // GGML_ABORT("unknown tensor name for tensor id %d", ...) in C++
    let tmpl = tensor
        .template()
        .unwrap_or_else(|| panic!("unknown tensor name for tensor {tensor:?}"));
    let mut out = String::with_capacity(tmpl.len() + 8);
    let mut next_arg = 0;
    let mut rest = tmpl;
    while let Some(pos) = rest.find("%d") {
        out.push_str(&rest[..pos]);
        let arg = if next_arg == 0 { blk } else { xid };
        out.push_str(&arg.to_string());
        next_arg += 1;
        rest = &rest[pos + 2..];
    }
    out.push_str(rest);
    out
}

/// `llm_arch_is_recurrent`
pub fn llm_arch_is_recurrent(arch: LlmArch) -> bool {
    matches!(
        arch,
        LlmArch::MAMBA
            | LlmArch::MAMBA2
            | LlmArch::RWKV6
            | LlmArch::RWKV6QWEN2
            | LlmArch::RWKV7
            | LlmArch::ARWKV7
    )
}

/// `llm_arch_is_hybrid`
pub fn llm_arch_is_hybrid(arch: LlmArch) -> bool {
    matches!(
        arch,
        LlmArch::JAMBA
            | LlmArch::FALCON_H1
            | LlmArch::PLAMO2
            | LlmArch::GRANITE_HYBRID
            | LlmArch::LFM2
            | LlmArch::LFM2MOE
            | LlmArch::NEMOTRON_H
            | LlmArch::NEMOTRON_H_MOE
            | LlmArch::QWEN3NEXT
            | LlmArch::KIMI_LINEAR
            | LlmArch::BAILINGMOE3
            | LlmArch::KIMI_K3
            | LlmArch::GLM5_NEXT
            | LlmArch::QWEN35
            | LlmArch::QWEN35MOE
            | LlmArch::QWEN4EXP
            | LlmArch::DEEPSEEK4
            | LlmArch::MINIMAX_01
    )
}

/// `llm_arch_is_diffusion`
pub fn llm_arch_is_diffusion(arch: LlmArch) -> bool {
    matches!(
        arch,
        LlmArch::DREAM | LlmArch::LLADA | LlmArch::LLADA_MOE | LlmArch::RND1
    )
}

/// `llm_arch_supports_rs_rollback`
pub fn llm_arch_supports_rs_rollback(arch: LlmArch) -> bool {
    matches!(
        arch,
        LlmArch::KIMI_K3
            | LlmArch::QWEN35
            | LlmArch::QWEN35MOE
            | LlmArch::QWEN4EXP
            | LlmArch::DEEPSEEK4
            | LlmArch::GLM5_NEXT
            | LlmArch::NEMOTRON_H
            | LlmArch::NEMOTRON_H_MOE
            | LlmArch::LFM2
            | LlmArch::LFM2MOE
            | LlmArch::BAILINGMOE3
    )
}

/// `llm_arch_supports_sm_tensor`
pub fn llm_arch_supports_sm_tensor(arch: LlmArch) -> bool {
    !matches!(
        arch,
        LlmArch::GROK
            | LlmArch::MPT
            | LlmArch::PLAMO2
            | LlmArch::MINICPM3
            | LlmArch::GEMMA3N
            | LlmArch::MAMBA
            | LlmArch::MAMBA2
            | LlmArch::JAMBA
            | LlmArch::FALCON_H1
            | LlmArch::OLMO2
            | LlmArch::OLMOE
            | LlmArch::DEEPSEEK2
            | LlmArch::DEEPSEEK32
            | LlmArch::HY_V4
            | LlmArch::DOTS3NOTE
            | LlmArch::GLM_DSA
            | LlmArch::BITNET
            | LlmArch::T5
            | LlmArch::NEMOTRON_H
            | LlmArch::NEMOTRON_H_MOE
            | LlmArch::GRANITE_HYBRID
            | LlmArch::MINIMAX_01
            | LlmArch::MINIMAX_M2
            | LlmArch::MINIMAX_M3
            | LlmArch::MISTRAL4
            | LlmArch::KIMI_LINEAR
            | LlmArch::BAILINGMOE3
            | LlmArch::KIMI_K3
            | LlmArch::GLM5_NEXT
            | LlmArch::QWEN3TTS
            | LlmArch::K2_HORIZON
    )
}

/// `llm_arch_supports_mixed_batch` (c35b66744) — these models pick weights,
/// routing or input meaning per ubatch based on token vs embd input.
pub fn llm_arch_supports_mixed_batch(arch: LlmArch) -> bool {
    !matches!(
        arch,
        LlmArch::COGVLM
            | LlmArch::DEEPSEEK4
            | LlmArch::GRANITE_SWITCH
            | LlmArch::EAGLE3
            | LlmArch::DFLASH
            | LlmArch::GEMMA4_ASSISTANT
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn arch_names_roundtrip() {
        for &a in LlmArch::ALL {
            if a == LlmArch::UNKNOWN {
                continue; // "(unknown)" parses back to UNKNOWN too, but skip the tautology
            }
            assert_eq!(LlmArch::from_name(a.name()), Some(a), "arch {:?}", a);
        }
    }

    #[test]
    fn arch_from_string_spot_checks() {
        assert_eq!(LlmArch::from_name("qwen2"), Some(LlmArch::QWEN2));
        assert_eq!(LlmArch::from_name("llama"), Some(LlmArch::LLAMA));
        assert_eq!(LlmArch::from_name("gpt-oss"), Some(LlmArch::OPENAI_MOE));
        assert_eq!(LlmArch::from_name("ernie4_5"), Some(LlmArch::ERNIE4_5));
        assert_eq!(
            LlmArch::from_name("ernie4_5-moe"),
            Some(LlmArch::ERNIE4_5_MOE)
        );
        assert_eq!(LlmArch::from_name("lfm2"), Some(LlmArch::LFM2));
        assert_eq!(LlmArch::from_name("gemma3"), Some(LlmArch::GEMMA3));
        assert_eq!(LlmArch::from_name("deepseek2"), Some(LlmArch::DEEPSEEK2));
        assert_eq!(LlmArch::from_name("bert"), Some(LlmArch::BERT));
        assert_eq!(LlmArch::from_name("no-such-arch"), None);
    }

    #[test]
    fn kv_names_arch_prefixed_and_fixed() {
        // arch-specific keys take the arch prefix (the documented pitfall)
        assert_eq!(
            kv_name(LlmArch::QWEN2, LlmKv::BLOCK_COUNT),
            "qwen2.block_count"
        );
        assert_eq!(
            kv_name(LlmArch::QWEN2, LlmKv::ATTENTION_HEAD_COUNT),
            "qwen2.attention.head_count"
        );
        assert_eq!(
            kv_name(LlmArch::QWEN2, LlmKv::ROPE_FREQ_BASE),
            "qwen2.rope.freq_base"
        );
        assert_eq!(
            kv_name(LlmArch::LLAMA, LlmKv::CONTEXT_LENGTH),
            "llama.context_length"
        );
        assert_eq!(
            kv_name(LlmArch::DEEPSEEK2, LlmKv::ATTENTION_KEY_LENGTH_MLA),
            "deepseek2.attention.key_length_mla"
        );
        // tokenizer/general/split/adapter keys carry NO arch prefix
        assert_eq!(
            kv_name(LlmArch::QWEN2, LlmKv::TOKENIZER_MODEL),
            "tokenizer.ggml.model"
        );
        assert_eq!(
            kv_name(LlmArch::QWEN2, LlmKv::TOKENIZER_BOS_ID),
            "tokenizer.ggml.bos_token_id"
        );
        assert_eq!(
            kv_name(LlmArch::QWEN2, LlmKv::GENERAL_ARCHITECTURE),
            "general.architecture"
        );
        assert_eq!(kv_name(LlmArch::QWEN2, LlmKv::SPLIT_NO), "split.no");
        assert_eq!(
            kv_name(LlmArch::QWEN2, LlmKv::ATTENTION_SLIDING_WINDOW),
            "qwen2.attention.sliding_window"
        );
        assert_eq!(
            kv_name(LlmArch::GEMMA3, LlmKv::ATTENTION_SLIDING_WINDOW),
            "gemma3.attention.sliding_window"
        );
    }

    #[test]
    fn tensor_names_block_templates() {
        assert_eq!(tensor_name(LlmTensor::TOKEN_EMBD, -1), "token_embd");
        assert_eq!(tensor_name(LlmTensor::OUTPUT_NORM, -1), "output_norm");
        assert_eq!(tensor_name(LlmTensor::OUTPUT, -1), "output");
        assert_eq!(tensor_name(LlmTensor::ATTN_NORM, 0), "blk.0.attn_norm");
        assert_eq!(tensor_name(LlmTensor::ATTN_NORM, 23), "blk.23.attn_norm");
        assert_eq!(tensor_name(LlmTensor::FFN_GATE, 5), "blk.5.ffn_gate");
        assert_eq!(
            tensor_name(LlmTensor::FFN_DOWN_EXPS, 3),
            "blk.3.ffn_down_exps"
        );
        // two-%d template: block id + expert id
        assert_eq!(
            tensor_name_xid(LlmTensor::FFN_GATE_EXP, 3, 7),
            "blk.3.ffn_gate.7"
        );
        // suffix variant used all over llama-model.cpp
        assert_eq!(
            tensor_name_suffix(LlmTensor::TOKEN_EMBD, "weight", -1, -1),
            "token_embd.weight"
        );
        assert_eq!(
            tensor_name_suffix(LlmTensor::ATTN_NORM, "weight", 0, -1),
            "blk.0.attn_norm.weight"
        );
        assert_eq!(
            tensor_name_suffix(LlmTensor::OUTPUT_NORM, "weight", -1, -1),
            "output_norm.weight"
        );
        // LFM2 wrong-name fix entry
        assert_eq!(
            tensor_name(LlmTensor::OUTPUT_NORM_LFM2, -1),
            "token_embd_norm"
        );
        // dec/enc prefixes (T5)
        assert_eq!(tensor_name(LlmTensor::DEC_ATTN_Q, 2), "dec.blk.2.attn_q");
        // no name in table -> C++ aborts; we panic (untestable via safe API, check template)
        assert_eq!(LlmTensor::SSM_CONV1D.template(), Some("blk.%d.ssm_conv1d"));
    }

    #[test]
    fn arch_classifications() {
        assert!(llm_arch_is_recurrent(LlmArch::MAMBA));
        assert!(!llm_arch_is_recurrent(LlmArch::QWEN2));
        assert!(llm_arch_is_hybrid(LlmArch::LFM2));
        assert!(llm_arch_is_hybrid(LlmArch::QWEN3NEXT));
        assert!(!llm_arch_is_hybrid(LlmArch::QWEN3));
        assert!(llm_arch_is_diffusion(LlmArch::DREAM));
        assert!(!llm_arch_supports_sm_tensor(LlmArch::DEEPSEEK2));
        assert!(llm_arch_supports_sm_tensor(LlmArch::QWEN2));
        assert!(llm_arch_supports_rs_rollback(LlmArch::LFM2));
        assert!(!llm_arch_supports_rs_rollback(LlmArch::QWEN2));
        // tensor buffer-class spot checks from LLM_TENSOR_INFOS
        assert_eq!(LlmTensor::TOKEN_EMBD.layer(), LlmTensorLayer::INPUT);
        assert_eq!(LlmTensor::OUTPUT.layer(), LlmTensorLayer::OUTPUT);
        assert_eq!(LlmTensor::ATTN_NORM.layer(), LlmTensorLayer::REPEATING);
    }

    #[test]
    fn table_sizes_match_reference() {
        // guards against accidental table truncation; update when regenerating
        assert_eq!(LlmArch::ALL.len(), 157);
        assert_eq!(count_match_arms(), 254);
    }

    fn count_match_arms() -> usize {
        // count of named LlmKv variants == variants in the enum
        LLM_KV_COUNT
    }

    pub const LLM_KV_COUNT: usize = 254;
}
